# Ícono NekaStat (128 px) incrustado como respaldo si falta la carpeta assets/
_NEKASTAT_ICON_PNG_B64 = (
    ""
)


def _nekastat_icon():
    """Devuelve el QIcon de NekaStat: assets/ (ICO o PNG) o la copia incrustada."""
    import base64 as _b64
    from PyQt6.QtGui import QIcon as _QIcon, QPixmap as _QPixmap
    _base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    for _nombre in ("NekaStat.ico", "NekaStat_icono_256.png"):
        _ruta = os.path.join(_base, "assets", _nombre)
        if os.path.exists(_ruta):
            return _QIcon(_ruta)
    _pm = _QPixmap()
    _pm.loadFromData(_b64.b64decode(_NEKASTAT_ICON_PNG_B64))
    return _QIcon(_pm)

