class SplashScreen(QWidget):
    """Pantalla de inicio simple — logo + barra de progreso."""
    finished = pyqtSignal()

    def _on_configure_bloques(self):
        """Abre el diálogo de bloques de variables."""
        if self._dataset_info is None:
            QMessageBox.warning(self, "Sin datos", "Cargue un archivo primero.")
            return
        dlg = BloquesDialog(self._dataset_info, parent=self)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            info = self._dataset_info
            # Validar
            try:
                validate_bloques(info)
            except Exception as e:
                QMessageBox.critical(self, "Error en bloques", str(e))
                return
            # Mostrar resumen
            resumen = "\n".join(
                f"  • {nm}: {len(cols)} variables"
                for nm, cols in info.bloques_variables
            )
            self._status(
                f"Modo bloques: K={info.n_tablas} bloques, n={info.n_total_filas} individuos\n{resumen}"
            )
            self.btn_run.setEnabled(True)


    def __init__(self):
        super().__init__()
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint |
                            Qt.WindowType.WindowStaysOnTopHint)
        self.setFixedSize(560, 300)
        self._center()
        self._build_ui()
        # Auto-cerrar tras 2.5s
        QTimer.singleShot(2500, self._close)

    def _center(self):
        screen = QApplication.primaryScreen().geometry()
        self.move((screen.width()-self.width())//2,
                  (screen.height()-self.height())//2)

    def _build_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(40, 40, 40, 24)
        layout.setSpacing(4)

        title = QLabel(APP_NAME)
        title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        title.setFont(QFont("Arial", 46, QFont.Weight.Bold))
        title.setStyleSheet("color: white; letter-spacing: 8px;")

        subtitle = QLabel(f"{APP_FULL_NAME}\nSoftware de análisis multivariante de tablas múltiples")
        subtitle.setAlignment(Qt.AlignmentFlag.AlignCenter)
        subtitle.setFont(QFont("Arial", 11))
        subtitle.setStyleSheet("color: rgba(255,255,255,0.72);")

        author = QLabel(APP_AUTHOR)
        author.setAlignment(Qt.AlignmentFlag.AlignCenter)
        author.setFont(QFont("Arial", 10, QFont.Weight.Bold))
        author.setStyleSheet(f"color: {COLOR_SECONDARY}; margin-top: 6px;")

        self.progress = QProgressBar()
        self.progress.setRange(0, 100)
        self.progress.setValue(0)
        self.progress.setTextVisible(False)
        self.progress.setFixedHeight(4)
        self.progress.setStyleSheet(f"""
            QProgressBar {{ border: none; background: rgba(255,255,255,0.15); border-radius:2px; }}
            QProgressBar::chunk {{ background: {COLOR_SECONDARY}; border-radius:2px; }}
        """)

        ver = QLabel(f"{APP_NAME} v{APP_VERSION}  ·  STATIS Dual (Lavit et al., 1994)")
        ver.setAlignment(Qt.AlignmentFlag.AlignCenter)
        ver.setFont(QFont("Arial", 8))
        ver.setStyleSheet("color: rgba(255,255,255,0.3);")

        # Ícono + nombre en una fila
        icon_lbl = QLabel()
        icon_lbl.setPixmap(_nekastat_icon().pixmap(84, 84))
        icon_lbl.setFixedSize(84, 84)
        title_row = QHBoxLayout()
        title_row.addStretch()
        title_row.addWidget(icon_lbl)
        title_row.addSpacing(14)
        title_row.addWidget(title)
        title_row.addStretch()
        layout.addLayout(title_row)
        layout.addWidget(subtitle)
        layout.addWidget(author)
        layout.addStretch()
        layout.addWidget(self.progress)
        layout.addWidget(ver)

        self._prog_val = 0
        self._timer = QTimer()
        self._timer.timeout.connect(self._tick)
        self._timer.start(25)

    def _tick(self):
        self._prog_val += 1
        self.progress.setValue(self._prog_val)
        if self._prog_val >= 100:
            self._timer.stop()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        grad = QLinearGradient(0, 0, self.width(), self.height())
        grad.setColorAt(0.0, QColor(COLOR_PRIMARY))
        grad.setColorAt(1.0, QColor(COLOR_ACCENT))
        painter.fillRect(self.rect(), QBrush(grad))

    def _close(self):
        self._timer.stop()
        self.finished.emit()
        self.close()


