        self.combo_id = QComboBox()
        self.combo_id.addItem("— ninguna —")
        self.combo_id.addItems(self.info.all_columns)
        row_id.addWidget(self.combo_id)

        row_id.addSpacing(20)
        row_id.addWidget(QLabel("Estandarización:"))
        self.combo_std = QComboBox()
        self.combo_std.addItems([
            "Parcial (por dimensión)",
            "Total (global entre dimensiones)",
            "Ninguna",
        ])
        self.combo_std.setToolTip(
            "Parcial: z-score columna por columna dentro de cada dimensión.\n"
            "Total:   z-score global usando media/sd de todas las dimensiones juntas.\n"
            "         Equivale a estandarización TOTAL en R (ade4/SensoMineR)."
        )
