class _ZeroNaNDialog(QDialog):
    """
    Pregunta al usuario cómo tratar ceros y/o NaN en las variables.
    Se muestra después de las advertencias de validación, solo si hay celdas
    con cero o vacías en el panel.
    """

    def __init__(self, detalle: str, parent=None):
        super().__init__(parent)
        self.setWindowTitle("Tratamiento de valores especiales")
        self.setFixedWidth(500)
        self.setStyleSheet(QSS_GLOBAL)
        self.choice = "keep"   # default
        self._build_ui(detalle)

    def _build_ui(self, detalle: str):
        layout = QVBoxLayout(self)
        layout.setSpacing(14)
        layout.setContentsMargins(20, 20, 20, 20)

        # Ícono + título
        hdr = QHBoxLayout()
        icon = QLabel("⚠")
        icon.setFont(QFont("Arial", 22))
        icon.setStyleSheet(f"color: {COLOR_WARNING};")
        icon.setFixedWidth(36)
        ttl = QLabel("Se detectaron valores especiales en las variables")
        ttl.setFont(QFont("Arial", 12, QFont.Weight.Bold))
        ttl.setStyleSheet(f"color: {COLOR_PRIMARY};")
        ttl.setWordWrap(True)
        hdr.addWidget(icon)
        hdr.addWidget(ttl)
        layout.addLayout(hdr)

        # Detalle
        lbl_det = QLabel(f"<b>Detalle:</b> {detalle}")
        lbl_det.setWordWrap(True)
        lbl_det.setStyleSheet(f"color: {COLOR_TEXT}; font-size: 12px;")
        layout.addWidget(lbl_det)

        sep = QFrame()
        sep.setFrameShape(QFrame.Shape.HLine)
        sep.setStyleSheet("background: #E2E8F0;")
        layout.addWidget(sep)

        # Opciones con radio buttons (simulados con checkboxes exclusivos)
        lbl_q = QLabel("¿Cómo desea tratar estos valores?")
        lbl_q.setFont(QFont("Arial", 11, QFont.Weight.Bold))
        lbl_q.setStyleSheet(f"color: {COLOR_PRIMARY};")
        layout.addWidget(lbl_q)

        # Opción A: mantener ceros
        self.rb_keep = QCheckBox(
            "Mantener ceros como scores efectivos\n(recomendado cuando el cero representa un valor real,\nej. universidades sin ranking en ese indicador)"
        )
        self.rb_keep.setChecked(True)
        self.rb_keep.setStyleSheet("font-size: 12px;")
        self.rb_keep.stateChanged.connect(lambda s: self._exclusive(self.rb_keep))

        # Opción B: imputar media global
        self.rb_impute = QCheckBox(
            "Imputar con media global de cada variable\n(reemplaza cero y NaN por la media calculada sobre\n"
            " todos los valores no-cero del panel completo)"
        )
        self.rb_impute.setChecked(False)
        self.rb_impute.setStyleSheet("font-size: 12px;")
        self.rb_impute.stateChanged.connect(lambda s: self._exclusive(self.rb_impute))

        # Recuadros visuales para las opciones
        box_a = QGroupBox()
        box_a.setStyleSheet(f"QGroupBox {{ border: 1.5px solid {COLOR_ACCENT}; border-radius: 6px; padding: 8px; }}")
        vl_a = QVBoxLayout(box_a)
        vl_a.addWidget(self.rb_keep)

        box_b = QGroupBox()
        box_b.setStyleSheet("QGroupBox { border: 1.5px solid #CBD5E0; border-radius: 6px; padding: 8px; }")
        vl_b = QVBoxLayout(box_b)
        vl_b.addWidget(self.rb_impute)

        self._box_a = box_a
        self._box_b = box_b

        layout.addWidget(box_a)
        layout.addWidget(box_b)

        # Nota metodológica
        nota = QLabel(
            "<i>Nota: esta selección puede cambiarse en cualquier momento "
            "usando el checkbox 'Imputar ceros con media global' en el panel izquierdo.</i>"
        )
        nota.setWordWrap(True)
        nota.setStyleSheet(f"color: {COLOR_TEXT_LIGHT}; font-size: 10px;")
        layout.addWidget(nota)

        # Botón confirmar
        btn_ok = QPushButton("Confirmar y continuar")
        btn_ok.clicked.connect(self._on_ok)
        layout.addWidget(btn_ok)

    def _exclusive(self, sender):
        """Simula comportamiento de radio button."""
        if sender == self.rb_keep and self.rb_keep.isChecked():
            self.rb_impute.setChecked(False)
            self._box_a.setStyleSheet(f"QGroupBox {{ border: 1.5px solid {COLOR_ACCENT}; border-radius: 6px; padding: 8px; }}")
            self._box_b.setStyleSheet("QGroupBox { border: 1.5px solid #CBD5E0; border-radius: 6px; padding: 8px; }")
        elif sender == self.rb_impute and self.rb_impute.isChecked():
            self.rb_keep.setChecked(False)
            self._box_b.setStyleSheet(f"QGroupBox {{ border: 1.5px solid {COLOR_ACCENT}; border-radius: 6px; padding: 8px; }}")
            self._box_a.setStyleSheet("QGroupBox { border: 1.5px solid #CBD5E0; border-radius: 6px; padding: 8px; }")
        elif not self.rb_keep.isChecked() and not self.rb_impute.isChecked():
            # Evitar que queden ambos desmarcados
            sender.setChecked(True)

    def _refresh_var_checks(self):
        """Deshabilita automáticamente las columnas asignadas a TABLAS o FILAS."""
        col_b = self.combo_tabla.currentText()
        col_f = self.combo_fila.currentText()
        for col, cb in self.var_checks.items():
            if col in (col_b, col_f):
                cb.setChecked(False)
                cb.setEnabled(False)
                cb.setStyleSheet("color: #A0AEC0;")
            else:
                cb.setEnabled(True)
                cb.setStyleSheet("")

    def _on_ok(self):
        self.choice = "keep" if self.rb_keep.isChecked() else "impute_mean"
        self.accept()


