    def _run_cluster_optimal(self):
        """Búsqueda del k óptimo y muestra índices de validación."""
        from matplotlib.backends.backend_qt5agg import FigureCanvasQTAgg as FigureCanvas
        from PyQt6.QtWidgets import QSizePolicy

        s = self._statis_result
        if s is None: return

        modo_opt = getattr(self._dataset_info, 'modo', 'longitudinal')                    if self._dataset_info else 'longitudinal'
        if modo_opt == 'longitudinal':
            unit_cb_opt = getattr(self, 'combo_cl_unit', None) or self._cl_unit
            unit_opt = unit_cb_opt.currentText() if unit_cb_opt else "Tablas"
            if "Observaciones" in unit_opt:
                rows_opt = []
                for t in sorted(s.tablas):
                    if t in s.F_k:
                        for row in s.F_k[t]:
                            rows_opt.append(row)
                X = np.array(rows_opt, dtype=float)
            else:
                tablas_opt = sorted(s.tablas)
                X = np.array([s.F_k[t].mean(axis=0) for t in tablas_opt
                               if t in s.F_k])
        else:
            X_raw_opt = s.F_rows.astype(float)
            X = X_raw_opt * float(np.sqrt(X_raw_opt.shape[0]))
        k_max   = self._cl_kmax.value()
        method  = self._cl_method.currentText()
        meth_k  = "ward" if "Ward" in method else "kmeans"

        area = self._cluster_area
        while area.layout().count():
            item = area.layout().takeAt(0)
            if item.widget(): item.widget().deleteLater()

        try:
            df_val = optimal_k(X, k_max=k_max, method=meth_k)
            fig_val = plot_validation_indices(
                df_val,
                title=f"Índices de validación — {method} (k=2..{k_max})"
            )
            scroll_val = self._wrap_canvas_scroll(fig_val)
            area.layout().addWidget(scroll_val)

            # Tabla de índices
            tbl = QTableWidget(len(df_val), len(df_val.columns))
            tbl.setHorizontalHeaderLabels(list(df_val.columns))
            tbl.setVerticalHeaderLabels(["k="+str(k) for k in df_val.index])
            tbl.setHorizontalScrollBarPolicy(
                Qt.ScrollBarPolicy.ScrollBarAsNeeded)
            for r, (_, row) in enumerate(df_val.iterrows()):
                for c, val in enumerate(row):
                    it = QTableWidgetItem(str(val))
                    it.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                    tbl.setItem(r, c, it)
            tbl.resizeColumnsToContents()
            tbl.setMinimumHeight(140)
            tbl.setMaximumHeight(220)
            area.layout().addWidget(tbl)

            btn_exp = QPushButton("⬇ PNG / TIFF")
            btn_exp.setObjectName("btn_secondary")
            btn_exp.clicked.connect(
                lambda _, f=fig_val: self._export_static_fig(f, "cluster_validacion"))
            area.layout().addWidget(btn_exp)

        except Exception as e:
            import traceback
            lbl = QLabel(f"Error: {e}\n{traceback.format_exc()}")
            lbl.setWordWrap(True)
            lbl.setStyleSheet("color:red; font-size:10px;")
            area.layout().addWidget(lbl)


