    def _wrap_canvas_scroll(self, fig) -> QScrollArea:
        """
        Envuelve una figura matplotlib en un FigureCanvas de tamaño FIJO
        (igual a figsize × dpi, su tamaño natural) dentro de un QScrollArea
        con widgetResizable=False. Así el gráfico nunca se "achata"/comprime
        para caber en la pestaña — si no entra, aparece scroll horizontal
        y/o vertical, igual criterio en todas las pestañas de gráficos.
        """
        w_in, h_in = fig.get_size_inches()
        dpi = fig.dpi
        canvas = FigureCanvas(fig)
        canvas.setFixedSize(int(round(w_in * dpi)), int(round(h_in * dpi)))

        scroll = QScrollArea()
        scroll.setWidgetResizable(False)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setStyleSheet("QScrollArea { border: none; background: white; }")
        scroll.setWidget(canvas)
        return scroll

    def _set_error_tab(self, tab: QWidget, key: str):
        """Muestra mensaje de error en un tab cuando el gráfico falló."""
        if tab.layout():
            while tab.layout().count():
                item = tab.layout().takeAt(0)
                if item.widget():
                    item.widget().deleteLater()
        else:
            tab.setLayout(QVBoxLayout())
        lbl = QLabel(f"⚠  No se pudo generar el gráfico '{key}'.\nRevisa la consola para más detalles.")
        lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        lbl.setStyleSheet(f"color: {COLOR_ERROR}; font-size: 13px;")
        tab.layout().addWidget(lbl)

    def _set_fig_tab(self, tab: QWidget, fig,
                     fig_key: str,
                     plotly_fig=None,
                     plotly_name: str = "",
                     extra_btn=None):
        """Inserta un canvas matplotlib + botones de acción en un tab."""
        # Limpiar tab
        if tab.layout():
            while tab.layout().count():
                item = tab.layout().takeAt(0)
                if item.widget():
                    item.widget().deleteLater()
        else:
            tab.setLayout(QVBoxLayout())

        layout = tab.layout()
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(6)

        # Canvas matplotlib — tamaño natural + scroll si no cabe
        scroll = self._wrap_canvas_scroll(fig)
        layout.addWidget(scroll)

        # Botones de acción
        btn_row = QHBoxLayout()

        btn_png = QPushButton("⬇ PNG / TIFF")
        btn_png.setObjectName("btn_secondary")
        btn_png.setFixedHeight(32)
        btn_png.clicked.connect(lambda _, fk=fig_key: self._export_static(fk))
        btn_row.addWidget(btn_png)

        if plotly_fig is not None:
            btn_inter = QPushButton("🔍 Ver interactivo")
            btn_inter.setFixedHeight(32)
            btn_inter.clicked.connect(
                lambda _, pf=plotly_fig, pn=plotly_name: self._open_interactive(pf, pn)
            )
            btn_row.addWidget(btn_inter)

        if extra_btn is not None:
            lbl_extra, fn_extra = extra_btn
            btn_extra = QPushButton(lbl_extra)
            btn_extra.setFixedHeight(32)
            btn_extra.clicked.connect(fn_extra)
            btn_row.addWidget(btn_extra)

        btn_row.addStretch()
        layout.addLayout(btn_row)

