    def _show_raw_scores_table(self, info):
        """
        Muestra (dentro de la pestaña Datos, debajo del preview) la tabla de
        puntajes BRUTOS por tabla+fila — genérica, usa lo que el usuario
        mapeó (col_tabla/col_fila/cols_variables), sin asumir nombres fijos.
        Se puede llamar más de una vez (al remapear) sin duplicar la sección.
        """
        layout = self.tab_data_inner.layout()

        # Quitar el stretch final del preview (si existe) para no dejarlo
        # en medio de las secciones; se vuelve a agregar al final.
        last_item = layout.itemAt(layout.count() - 1) if layout.count() else None
        if last_item is not None and last_item.spacerItem() is not None:
            layout.removeItem(last_item)

        # Si ya existía una sección de puntajes brutos, quitarla primero
        # (evita duplicar si el usuario vuelve a mapear sin recargar archivo)
        old_widgets = getattr(self, "_raw_scores_widgets", [])
        for w in old_widgets:
            layout.removeWidget(w)
            w.deleteLater()
        self._raw_scores_widgets = []

        df_scores = build_raw_scores_table(info)
        self._raw_scores_df = df_scores

        lbl = QLabel("Puntajes brutos (dato original, previo a STATIS)")
        lbl.setObjectName("label_section")
        layout.addWidget(lbl)
        self._raw_scores_widgets.append(lbl)

        tbl = QTableWidget(len(df_scores), len(df_scores.columns))
        tbl.setHorizontalHeaderLabels(list(df_scores.columns))
        tbl.setAlternatingRowColors(True)
        for r in range(len(df_scores)):
            for c, col in enumerate(df_scores.columns):
                val = df_scores.iloc[r, c]
                txt = f"{val:.4f}" if isinstance(val, float) else str(val)
                tbl.setItem(r, c, QTableWidgetItem(txt))
        tbl.resizeColumnsToContents()
        tbl.setMaximumHeight(400)
        layout.addWidget(tbl)
        self._raw_scores_widgets.append(tbl)

        btn_export = QPushButton("💾 Exportar puntajes brutos a Excel")
        btn_export.clicked.connect(self._export_raw_scores_excel)
        layout.addWidget(btn_export)
        self._raw_scores_widgets.append(btn_export)

        layout.addStretch()

